import json, sys
PRICES = {('US', 'tea'): 5, ('EU', 'tea'): 7, ('US', 'coffee'): 8, ('EU', 'coffee'): 11}
def simulate(requests, mode='sku'):
    cache = {}
    replies = []
    origin_calls = 0
    for region, sku in requests:
        key = sku if mode == 'sku' else (region, sku)
        if mode == 'off' or key not in cache:
            origin_calls += 1
            cache[key] = PRICES[(region, sku)]
        replies.append(cache[key])
    return {'replies': replies, 'origin_calls': origin_calls}
def updating_requests(events):
    for event in events:
        for region, sku, price in event.get('updates', []):
            PRICES[(region, sku)] = price
        yield tuple(event['request'])
def simulate_invalidated(events):
    cache = {}
    replies = []
    origin_calls = 0
    for event in events:
        for region, sku, price in event.get('updates', []):
            key = (region, sku)
            PRICES[key] = price
            cache.pop(key, None)
        key = tuple(event['request'])
        if key not in cache:
            origin_calls += 1
            cache[key] = PRICES[key]
        replies.append(cache[key])
    return {'replies': replies, 'origin_calls': origin_calls}
data = json.load(sys.stdin)
initial = {(r, s): p for r, s, p in data['initial_prices']}
reports = {}
for name, case in data['cases'].items():
    events = case['events']
    expected = case['expected_replies']
    modes = {}
    for mode in ['sku', 'region_sku', 'off', 'region_sku_invalidation']:
        PRICES.clear()
        PRICES.update(initial)
        result = simulate_invalidated(events) if mode == 'region_sku_invalidation' else simulate(updating_requests(events), mode)
        result['response_count_matches'] = len(result['replies']) == len(expected)
        result['mismatches'] = [{'request_index': i, 'request': events[i]['request'], 'expected': wanted, 'actual': actual} for i, (wanted, actual) in enumerate(zip(expected, result['replies'])) if wanted != actual]
        result['all_correct'] = result['response_count_matches'] and not result['mismatches']
        modes[mode] = result
    reports[name] = {'events': events, 'expected_replies': expected, 'modes': modes}
static = reports['static']['modes']
update = reports['update']['modes']
checks = {'static_region_sku_correct_and_saving': static['region_sku']['all_correct'] and static['region_sku']['origin_calls'] < static['off']['origin_calls'], 'update_region_sku_has_stale_replies': not update['region_sku']['all_correct'], 'update_invalidation_correct_and_saving': update['region_sku_invalidation']['all_correct'] and update['region_sku_invalidation']['origin_calls'] < update['off']['origin_calls']}
json.dump({'experiment_key': 'cache-current-origin-challenger-v2', 'reports': reports, 'checks': checks, 'scope': 'Listed event sequences only; controlled in-iteration origin updates; notification-aware repair is a modeled extension; expected values are explicit test literals sharing the declaration source', 'units': {'origin_calls': 'calls'}}, sys.stdout)
